import os

for name, base in [('erase', 'extracted/ipsw/ramdisk_erase'), ('update', 'extracted/ipsw/ramdisk_update')]:
    abs_base = os.path.abspath(base)
    escapes = []
    for root, dirs, files in os.walk(base, followlinks=False):
        for item in dirs + files:
            p = os.path.join(root, item)
            if os.path.islink(p):
                target = os.readlink(p)
                resolved = os.path.abspath(os.path.join(root, target))
                if not resolved.startswith(abs_base):
                    escapes.append((p, target, resolved))
    print(f'{name} links escaping base dir ({len(escapes)}):', escapes)
